[2650]="70063CC9\n1\tDeliver the piles of dim dust to a collection box\030Collect piles of dim dust (total: 10)\tYou have accepted a task to acquire piles of dim dust.\n",
[2651]="70063CC4\n1\tDeliver the dusky ears to a collection box\030Collect dusky ears (total: 10)\tYou have accepted a task to acquire dusky ears.\n",
[2652]="70063CC3\n1\tDeliver the glossy essences to a collection box\030Collect glossy essences (total: 10)\tYou have accepted a task to acquire glossy essences.\n",
[2653]="70063CC1\n1\tDeliver the large finger bones to a collection box\030Collect large finger bones (total: 10)\tYou have accepted a task to acquire large finger bones.\n",
